public class Discount {
    public static final Decimal MAX_RATE = 0.3;   // 상수
    private Map<Id, Account> cache = new Map<Id, Account>();

    public Decimal apply(Decimal amount, Decimal rate) {
        return amount * (1 - Math.min(rate, MAX_RATE));
    }
}

