public class LeadScorer {
    @InvocableMethod(label='Score Leads')
    public static List<Integer> score(List<Id> leadIds) {
        List<Integer> scores = new List<Integer>();
        for (Lead l : [SELECT Rating FROM Lead WHERE Id IN :leadIds]) {
            scores.add(l.Rating == 'Hot' ? 90 : 40);
        }
        return scores;
    }
}

